/**
 * Regression test: a failing sandbox bootstrap/init must not wedge the gateway.
 *
 * `SandboxManager.ensureForProject(projectId)` runs the bootstrap closure and,
 * on success, initialises a ProjectSandbox. The original bug surfaced sandbox
 * setup failures BOTH on the awaited boundary AND as a dangling global
 * `unhandledRejection`, which under load could make the gateway unreachable for
 * unrelated sessions.
 *
 * This pins three invariants using a stub bootstrap we control (no Docker):
 *   (a) the awaited `ensureForProject` call rejects with the bootstrap error;
 *   (b) NO global `unhandledRejection` fires while/after that failure;
 *   (c) the manager stays usable — a subsequent `ensureForProject` for a
 *       different project whose bootstrap returns `null` (sandbox not
 *       applicable) resolves without throwing.
 */
import { describe, it } from "vitest";
import assert from "node:assert/strict";
import { SandboxManager, type SandboxBootstrap } from "../../src/server/agent/sandbox-manager.js";
import { ProjectSandbox } from "../../src/server/agent/project-sandbox.js";

describe("SandboxManager.ensureForProject failure isolation", () => {
	it("rejects on the awaited boundary, leaks no unhandledRejection, and stays usable", async () => {
		const BOOT_FAIL = "forced bootstrap failure local origin outside project root";

		// Stub bootstrap: throw for the broken project, return null (sandbox not
		// applicable) for any other project. Never returns real options, so we
		// never touch Docker.
		const bootstrap: SandboxBootstrap = async (projectId) => {
			if (projectId === "broken-project") {
				throw new Error(BOOT_FAIL);
			}
			return null;
		};

		const manager = new SandboxManager({ bootstrap });

		const rejections: unknown[] = [];
		const listener = (reason: unknown) => rejections.push(reason);
		process.on("unhandledRejection", listener);

		try {
			// (a) The awaited call must reject with the bootstrap error.
			await assert.rejects(
				() => manager.ensureForProject("broken-project"),
				new RegExp(BOOT_FAIL),
			);

			// Flush microtasks + timers so any dangling rejection can surface.
			await new Promise((r) => setTimeout(r, 100));

			// (b) No global unhandled rejection from the failed init.
			assert.equal(
				rejections.length,
				0,
				`failed sandbox init leaked ${rejections.length} unhandled rejection(s): ` +
					rejections.map((r) => (r instanceof Error ? r.message : String(r))).join(", "),
			);

			// (c) The manager is still usable for other projects.
			await assert.doesNotReject(() => manager.ensureForProject("healthy-other-project"));
			assert.equal(manager.has("healthy-other-project"), false, "null bootstrap registers nothing");

			// And the broken project can be retried (in-flight entry was cleared).
			await assert.rejects(
				() => manager.ensureForProject("broken-project"),
				new RegExp(BOOT_FAIL),
			);
			await new Promise((r) => setTimeout(r, 50));
			assert.equal(rejections.length, 0, "retry must not leak a rejection either");
		} finally {
			process.off("unhandledRejection", listener);
		}
	});

	it("creates a separate verification backend without initializing a mutable project container", async () => {
		const manager = new SandboxManager({
			bootstrap: async () => ({
				projectId: "verification-only-project",
				projectDir: process.cwd(),
				repoUrl: "",
				image: "prepared-verifier-image",
			}),
		});

		await manager.ensureVerificationBackend("verification-only-project");
		assert.equal(manager.has("verification-only-project"), false);
		assert.equal((manager as any)._verificationBackends.get("verification-only-project")?.sandbox.getStatus().status, "starting",
			"verification preparation must not create the long-lived mutable project container");
	});

	it("requests a verification backend independently of direct-agent sandbox policy", async () => {
		const purposes: string[] = [];
		const manager = new SandboxManager({
			bootstrap: async (_projectId, purpose) => {
				purposes.push(purpose ?? "session");
				return null;
			},
		});

		await manager.ensureForProject("direct-project");
		await manager.ensureVerificationBackend("direct-project");
		assert.deepEqual(purposes, ["session", "verification"]);
		assert.equal(manager.has("direct-project"), false);
	});

	it("runs a ready B verification image instead of the live A session image", async () => {
		const projectId = "plan-change-project";
		const bootstraps: string[] = [];
		const manager = new SandboxManager({
			bootstrap: async (_id, purpose) => {
				bootstraps.push(purpose ?? "session");
				return purpose === "verification"
					? { projectId, projectDir: process.cwd(), repoUrl: "", image: "image-b", sandboxImageFingerprint: "fingerprint-b", sandboxCredentials: { SECRET: "must-not-reach-sidecar" }, githubToken: "must-not-reach-sidecar" }
					: { projectId, projectDir: process.cwd(), repoUrl: "", image: "image-a", sandboxImageFingerprint: "fingerprint-a" };
			},
		});
		const sessionSandbox = { getStatus: () => ({ projectId, status: "ready", containerId: "container-a" }) };
		(manager as any).sandboxes.set(projectId, sessionSandbox);
		(manager as any)._appliedImagePlans.set(projectId, { image: "image-a", fingerprint: "fingerprint-a" });

		const original = ProjectSandbox.prototype.getVerificationSidecar;
		const dockerRuns: Array<{ image: string; fingerprint?: string; credentials?: unknown; githubToken?: unknown }> = [];
		ProjectSandbox.prototype.getVerificationSidecar = async function(request) {
			const options = (this as any).options;
			dockerRuns.push({ image: options.image, fingerprint: options.sandboxImageFingerprint, credentials: options.sandboxCredentials, githubToken: options.githubToken });
			return { containerId: "b".repeat(64), projectId: options.projectId, signalId: request.signalId, checkoutPath: request.checkoutPath, cwd: "/verified-b" };
		};
		try {
			const sidecar = await manager.getVerificationSidecar(projectId, { signalId: "signal-b", checkoutPath: process.cwd(), ignoredOutputDirs: [] });
			assert.equal(sidecar.cwd, "/verified-b");
			assert.deepEqual(bootstraps, ["verification"], "every sidecar request must run the no-build exact-image bootstrap");
			assert.deepEqual(dockerRuns, [{ image: "image-b", fingerprint: "fingerprint-b", credentials: undefined, githubToken: undefined }]);
			assert.equal(manager.get(projectId), sessionSandbox, "verification must not replace or damage live A");
		} finally {
			ProjectSandbox.prototype.getVerificationSidecar = original;
		}
	});

	it("retains A's exact validator after B becomes current, then reaps both without destroying a live project volume", async () => {
		const projectId = "superseded-verification-project";
		let image = "image-a";
		const manager = new SandboxManager({
			bootstrap: async () => ({ projectId, projectDir: process.cwd(), repoUrl: "", image, sandboxImageFingerprint: image }),
		});
		const originalAcquire = ProjectSandbox.prototype.getVerificationSidecar;
		const originalRemove = ProjectSandbox.prototype.removeVerificationSidecar;
		const originalRecover = ProjectSandbox.prototype.recoverVerificationSidecars;
		const originalDestroy = ProjectSandbox.prototype.destroy;
		const removals: string[] = [];
		const reaped: string[] = [];
		ProjectSandbox.prototype.getVerificationSidecar = async function(request) {
			const options = (this as any).options;
			return { containerId: "a".repeat(64), projectId: options.projectId, signalId: request.signalId, checkoutPath: request.checkoutPath, cwd: "/verified" };
		};
		ProjectSandbox.prototype.removeVerificationSidecar = async function() {
			const candidateImage = (this as any).options.image;
			removals.push(candidateImage);
			if (candidateImage !== "image-a") throw new Error("strict image validation rejected A-owned sidecar");
		};
		ProjectSandbox.prototype.recoverVerificationSidecars = async function() {
			reaped.push((this as any).options.image);
			return [];
		};
		ProjectSandbox.prototype.destroy = async function() {
			throw new Error("verification backend teardown must not destroy a project volume");
		};
		try {
			await manager.getVerificationSidecar(projectId, { signalId: "signal-a", checkoutPath: process.cwd(), ignoredOutputDirs: [] });
			image = "image-b";
			await manager.getVerificationSidecar(projectId, { signalId: "signal-b", checkoutPath: process.cwd(), ignoredOutputDirs: [] });
			await manager.removeVerificationSidecar(projectId, { signalId: "signal-a", checkoutPath: process.cwd(), containerId: "a".repeat(64), ignoredOutputDirs: [] });
			assert.deepEqual(removals, ["image-b", "image-a"], "cleanup tries only strict current and retained exact validators");

			await manager.destroy(projectId);
			assert.deepEqual(reaped, ["image-b", "image-a"], "teardown reaps each bounded backend exactly once");
			assert.equal((manager as any)._verificationBackends.has(projectId), false);
			assert.equal((manager as any)._supersededVerificationBackends.has(projectId), false);
		} finally {
			ProjectSandbox.prototype.getVerificationSidecar = originalAcquire;
			ProjectSandbox.prototype.removeVerificationSidecar = originalRemove;
			ProjectSandbox.prototype.recoverVerificationSidecars = originalRecover;
			ProjectSandbox.prototype.destroy = originalDestroy;
		}
	});

	it("rejects sidecar removal when the exact verification bootstrap is unavailable", async () => {
		const manager = new SandboxManager({
			bootstrap: async () => { throw new Error("verification bootstrap unavailable"); },
		});
		await assert.rejects(
			() => manager.removeVerificationSidecar("unavailable-project", { signalId: "signal-a", checkoutPath: process.cwd(), containerId: "a".repeat(64), ignoredOutputDirs: [] }),
			/verification bootstrap unavailable/,
		);
	});

	it("runs verification bootstrap and B while A session initialization is in flight", async () => {
		const projectId = "concurrent-plan-change-project";
		const purposes: string[] = [];
		let releaseInit!: () => void;
		let sessionPublished!: () => void;
		const initReleased = new Promise<void>((resolve) => { releaseInit = resolve; });
		const sessionPublishedPromise = new Promise<void>((resolve) => { sessionPublished = resolve; });
		const manager = new SandboxManager({
			bootstrap: async (_id, purpose) => {
				purposes.push(purpose ?? "session");
				return purpose === "verification"
					? { projectId, projectDir: process.cwd(), repoUrl: "", image: "image-b", sandboxImageFingerprint: "fingerprint-b" }
					: { projectId, projectDir: process.cwd(), repoUrl: "", image: "image-a", sandboxImageFingerprint: "fingerprint-a" };
			},
		});
		const sessionSandbox = { getStatus: () => ({ projectId, status: "starting", containerId: "" }) };
		(manager as any).initForProject = async () => {
			(manager as any).sandboxes.set(projectId, sessionSandbox);
			sessionPublished();
			await initReleased;
		};

		const original = ProjectSandbox.prototype.getVerificationSidecar;
		const dockerRunImages: string[] = [];
		ProjectSandbox.prototype.getVerificationSidecar = async function(request) {
			const options = (this as any).options;
			dockerRunImages.push(options.image);
			return { containerId: "b".repeat(64), projectId: options.projectId, signalId: request.signalId, checkoutPath: request.checkoutPath, cwd: "/verified-b" };
		};
		try {
			const sessionInit = manager.ensureForProject(projectId);
			await sessionPublishedPromise;
			await manager.getVerificationSidecar(projectId, { signalId: "signal-b", checkoutPath: process.cwd(), ignoredOutputDirs: [] });
			assert.deepEqual(purposes, ["session", "verification"], "in-flight A must not suppress B's exact-image verification bootstrap");
			assert.deepEqual(dockerRunImages, ["image-b"], "the sidecar Docker run must use verified B");
			assert.equal(manager.get(projectId), sessionSandbox, "verification must not replace the initializing session sandbox");
			releaseInit();
			await sessionInit;
		} finally {
			ProjectSandbox.prototype.getVerificationSidecar = original;
		}
	});
});
